import React, { useRef, useEffect } from "react";
import { motion, useScroll, useTransform } from "framer-motion";
import { Sparkles, ArrowDown, Crown, Calendar } from "lucide-react";
import { BRAND } from "../types";

const FRAMES = [
  "/images/frames/frame_1.png",
  "/images/frames/frame_2.png",
  "/images/frames/frame_3.png",
  "/images/frames/frame_4.png",
  "/images/frames/frame_5.png",
  "/images/frames/frame_6.png",
  "/images/frames/frame_7.png",
  "/images/frames/frame_8.png",
  "/images/frames/frame_9.png",
];

interface HeroScrollProps {
  onOpenQuote?: () => void;
}

export default function HeroScroll({ onOpenQuote }: HeroScrollProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  // Track scroll progress of the entire container (250vh scroll track)
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"],
  });

  // Use scroll progress directly for instantaneous scroll response
  const smoothProgress = scrollYProgress;

  // Background scale zooms in (up to 1.22) and back out to 1.0
  const bgScale = useTransform(smoothProgress, [0, 0.5, 1], [1.0, 1.22, 1.0]);
  const bgOpacity = useTransform(smoothProgress, [0, 0.7, 1], [0.95, 0.9, 0.85]);

  // Frame 1 Animations: Logo & Title (visible from 0% to 30% scroll)
  const frame1Opacity = useTransform(smoothProgress, [0, 0.22, 0.28], [1, 1, 0]);
  const frame1Y = useTransform(smoothProgress, [0, 0.28], [0, -80]);
  const frame1Scale = useTransform(smoothProgress, [0, 0.28], [1, 0.9]);



  // Frame 3 Animations: Calls to Action (visible from 72% to 100% scroll)
  const frame3Opacity = useTransform(smoothProgress, [0.72, 0.85, 1], [0, 1, 1]);
  const frame3Y = useTransform(smoothProgress, [0.72, 0.88], [80, 0]);
  const frame3Scale = useTransform(smoothProgress, [0.72, 0.88], [0.92, 1]);

  // General helpers
  const arrowOpacity = useTransform(smoothProgress, [0, 0.12], [1, 0]);

  // Preload frame images to avoid flickering during scrolling
  useEffect(() => {
    FRAMES.forEach((src) => {
      const img = new Image();
      img.src = src;
    });
  }, []);

  const scrollToCollections = () => {
    document.getElementById("collections")?.scrollIntoView({ behavior: "smooth" });
  };

  const handleOpenQuote = () => {
    if (onOpenQuote) {
      onOpenQuote();
    } else {
      document.getElementById("contact")?.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <div ref={containerRef} className="relative h-[250vh] bg-dark overflow-visible">
      {/* Sticky viewport wrapper */}
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center">

        {/* Immersive background media with parallax zoom */}
        <motion.div
          className="absolute inset-0 overflow-hidden"
          style={{
            scale: bgScale,
            opacity: bgOpacity,
            willChange: "transform, opacity",
          }}
        >
          {/* Render all frames and crossfade their opacity on scroll */}
          {FRAMES.map((src, i) => {
            const start = i === 0 ? 0 : (i - 0.5) / 8;
            const peak = i / 8;
            const end = i === 8 ? 1 : (i + 0.5) / 8;

            const opacity = useTransform(smoothProgress, [start, peak, end], [0, 1, 0]);

            return (
              <motion.img
                key={i}
                src={src}
                alt={`Wedding Venue Frame ${i + 1}`}
                style={{ opacity }}
                className="absolute inset-0 w-full h-full object-cover"
                loading="eager"
              />
            );
          })}
        </motion.div>

        {/* Ambient Dark Overlays */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-black/40 to-black/95 pointer-events-none" />
        <div className="absolute inset-0 bg-radial-gradient(ellipse at center, transparent 30%, rgba(0,0,0,0.8) 100%) pointer-events-none" />

        {/* Custom CSS for offloading sparks animation to GPU compositor */}
        <style>{`
          @keyframes floatSpark {
            0% {
              transform: translateY(0) scale(0.2);
              opacity: 0;
            }
            50% {
              opacity: 0.7;
            }
            100% {
              transform: translateY(-90px) scale(1.25);
              opacity: 0;
            }
          }
          .gpu-spark {
            animation: floatSpark var(--duration) ease-in-out var(--delay) infinite;
            will-change: transform, opacity;
          }
        `}</style>

        {/* Floating Sparks (GPU Accelerated) */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none z-10">
          {[...Array(14)].map((_, i) => {
            const size = 1 + (i % 3) * 0.5;
            const duration = 4.5 + (i % 4) * 0.8;
            const delay = i * 0.3;
            return (
              <div
                key={i}
                className="absolute rounded-full gpu-spark"
                style={{
                  width: size,
                  height: size,
                  left: `${5 + ((i * 7.3) % 90)}%`,
                  top: `${10 + ((i * 8.7) % 80)}%`,
                  background: `rgba(212, 175, 55, ${0.25 + (i % 3) * 0.15})`,
                  "--duration": `${duration}s`,
                  "--delay": `${delay}s`,
                } as React.CSSProperties}
              />
            );
          })}
        </div>

        {/* ── FRAME 1: Heading and Tagline (Start of Scroll) ── */}
        <motion.div
          style={{
            opacity: frame1Opacity,
            y: frame1Y,
            scale: frame1Scale,
          }}
          className="absolute z-20 text-center px-6 w-full max-w-5xl text-white"
        >
          {/* Location Badge */}
          <div className="flex items-center justify-center gap-3 mb-6">
            <span className="h-px w-10 bg-amber-400/40" />
            <span className="text-amber-400 font-semibold tracking-[0.25em] text-xs md:text-sm uppercase">
              Ludhiana, Punjab
            </span>
            <span className="h-px w-10 bg-amber-400/40" />
          </div>

          {/* Main Logo Text */}
          <h1
            className="text-6xl md:text-8xl lg:text-[110px] font-bold text-white tracking-tight leading-none mb-6 drop-shadow-lg"
            style={{ fontFamily: "Georgia, serif" }}
          >
            {BRAND.name}
          </h1>

          {/* Tagline */}
          <div className="flex items-center justify-center gap-3 mb-6">
            <Crown className="text-amber-400/80 shrink-0" size={24} />
            <p
              className="text-2xl md:text-4xl text-amber-400 italic drop-shadow"
              style={{ fontFamily: "Georgia, serif" }}
            >
              {BRAND.tagline}
            </p>
            <Crown className="text-amber-400/80 shrink-0" size={24} />
          </div>

          <p className="text-white/70 text-sm md:text-base max-w-xl mx-auto tracking-wide leading-relaxed">
            Premium fabrics and installations for India's grandest celebrations. Scroll down to begin the design journey.
          </p>
        </motion.div>


        {/* ── FRAME 2: Product Showcase Cards (Mid Scroll) ── */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
          <div className="container mx-auto px-6 grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8 max-w-6xl pointer-events-auto">

            {/* Card 1: Ceiling Drapes */}
            <motion.div
              style={{
                x: card1X,
                opacity: card1Opacity,
              }}
              className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-6 md:p-8 flex flex-col justify-between shadow-2xl transition-all duration-300 hover:bg-white/10 hover:border-amber-400/40"
            >
              <div>
                <span className="text-amber-400 text-xs font-bold uppercase tracking-wider block mb-3">
                  Aesthetic 01
                </span>
                <h3 className="text-2xl font-bold text-white mb-4" style={{ fontFamily: "Georgia, serif" }}>
                  Ceiling Drapes
                </h3>
                <p className="text-white/60 text-sm leading-relaxed">
                  Breathtaking ivory and champagne silk fabric installations that flow with symmetry and elegance, creating an overhead canopy of dreams.
                </p>
              </div>
              <div className="h-1 w-12 bg-amber-400 rounded-full mt-6" />
            </motion.div>

            {/* Card 2: Table & Seating */}
            <motion.div
              style={{
                y: card2Y,
                opacity: card2Opacity,
              }}
              className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-6 md:p-8 flex flex-col justify-between shadow-2xl transition-all duration-300 hover:bg-white/10 hover:border-amber-400/40"
            >
              <div>
                <span className="text-amber-400 text-xs font-bold uppercase tracking-wider block mb-3">
                  Aesthetic 02
                </span>
                <h3 className="text-2xl font-bold text-white mb-4" style={{ fontFamily: "Georgia, serif" }}>
                  Table & Chair Covers
                </h3>
                <p className="text-white/60 text-sm leading-relaxed">
                  Luxe table drapes paired with signature chair covers and satin bows, forming a harmonious palette that frames guests in pure luxury.
                </p>
              </div>
              <div className="h-1 w-12 bg-amber-400 rounded-full mt-6" />
            </motion.div>

            {/* Card 3: Decor Details */}
            <motion.div
              style={{
                x: card3X,
                opacity: card3Opacity,
              }}
              className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-6 md:p-8 flex flex-col justify-between shadow-2xl transition-all duration-300 hover:bg-white/10 hover:border-amber-400/40"
            >
              <div>
                <span className="text-amber-400 text-xs font-bold uppercase tracking-wider block mb-3">
                  Aesthetic 03
                </span>
                <h3 className="text-2xl font-bold text-white mb-4" style={{ fontFamily: "Georgia, serif" }}>
                  Finishing Accents
                </h3>
                <p className="text-white/60 text-sm leading-relaxed">
                  Premium floral arrangements, golden candelabras, crystal chandeliers, and customized props that complete the grand wedding vision.
                </p>
              </div>
              <div className="h-1 w-12 bg-amber-400 rounded-full mt-6" />
            </motion.div>

          </div>
        </div>


        {/* ── FRAME 3: CTA Section (End of Scroll) ── */}
        <motion.div
          style={{
            opacity: frame3Opacity,
            y: frame3Y,
            scale: frame3Scale,
          }}
          className="absolute z-20 text-center px-6 w-full max-w-4xl"
        >
          <motion.div
            animate={{ rotate: [0, 5, -5, 0] }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
            className="inline-block mb-6 text-amber-400"
          >
            <Sparkles size={40} className="mx-auto" />
          </motion.div>

          <h2
            className="text-4xl md:text-6xl font-bold text-white mb-6 leading-tight"
            style={{ fontFamily: "Georgia, serif" }}
          >
            Adorning Venues with <br />
            <span className="text-amber-400">Timeless Elegance</span>
          </h2>

          <p className="text-white/70 text-base md:text-lg max-w-2xl mx-auto mb-10 leading-relaxed">
            From majestic drapes to delicate tabletop finishes, explore how D SAJAWAT turns empty banquets and gardens into luxurious wedding landmarks.
          </p>

          <div className="flex flex-col sm:flex-row gap-5 justify-center">
            <button
              onClick={scrollToCollections}
              className="px-10 py-4.5 bg-gradient-to-r from-amber-400 to-amber-500 text-white font-bold rounded-full flex items-center justify-center gap-3 text-base shadow-2xl shadow-amber-500/35 relative overflow-hidden group hover:scale-105 transition-all duration-300"
            >
              <span className="relative z-10">Explore Collections</span>
              <span className="relative z-10">→</span>
              <div className="absolute inset-0 bg-white/20 -skew-x-12 -translate-x-full group-hover:translate-x-full transition-transform duration-700" />
            </button>

            <button
              onClick={handleOpenQuote}
              className="px-10 py-4.5 bg-white/10 backdrop-blur-xl border border-white/20 text-white font-bold rounded-full flex items-center justify-center gap-3 text-base hover:bg-white hover:text-dark hover:scale-105 transition-all duration-300"
            >
              <Calendar size={18} />
              <span>Get Quote</span>
            </button>
          </div>
        </motion.div>


        {/* Scroll Indicator (Visible initially, fades as you scroll) */}
        <motion.div
          style={{ opacity: arrowOpacity }}
          className="absolute bottom-10 left-1/2 -translate-x-1/2 z-25 text-center flex flex-col items-center gap-2"
        >
          <p className="text-white/60 text-xs uppercase tracking-[0.2em] font-medium">
            Scroll to begin
          </p>
          <motion.div
            animate={{ y: [0, 8, 0] }}
            transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
            className="w-8 h-8 rounded-full border border-white/20 flex items-center justify-center bg-white/5 backdrop-blur-sm"
          >
            <ArrowDown className="text-amber-400" size={14} />
          </motion.div>
        </motion.div>

      </div>

      {/* Background spacer for the remainder of the scroll track */}
      <div className="h-px bg-transparent pointer-events-none" />
    </div>
  );
}
